fo = fullfile(fileparts(fileparts(fileparts(mfilename('fullpath')))), 'test_results', 'temp_3d_wsonly');  load(fullfile(fo, 'temp_1104_square_circle_s1.mat'), 'r');  FS = 15;  cT = [0.85 0 0];  cE = [0 0.25 0.85];  th = char(952);  hc = char(770);
